// Attach photos and cover image to each project.
export const projects = projectDefinitions.map((p) => {
  const photos = imagesByProject(p.slug);
  const cover = photos.find((img) => img.src && img.src.includes(p.cover.replace('.jpg', ''))) || photos[0];
  return { ...p, photos, coverImage: cover };
});

export const getProject = (slug) => projects.find((p) => p.slug === slug);
